pub fn flush(self: *Cloner) anyerror!void {
            const max_package_id = self.old.packages.len;
            while (self.clone_queue.pop()) |to_clone| {
                const mapping = self.mapping[@as(usize, @intCast(to_clone.old_resolution))];
                if ((mapping < max_package_id)) {
                    self.lockfile.buffers.resolutions.items[cp_cast_int(usize, to_clone.resolve_id)] = mapping;
                    continue;
                }
                const old_package = self.old.packages.get(to_clone.old_resolution);
                self.lockfile.buffers.resolutions.items[cp_cast_int(usize, to_clone.resolve_id)] = try old_package.clone(self.manager, self.old, self.lockfile, self.mapping, self);
            }
            _ = self.manager.clearCachedItemsDependingOnLockfileBuffer();
            if ((self.lockfile.packages.len != 0)) {
                _ = try self.lockfile.resolve(self.log);
            }
            if (((self.lockfile.packages.capacity != self.lockfile.packages.len) and (self.lockfile.packages.len > 0))) {
                _ = self.lockfile.packages.shrinkAndFree(self.lockfile.allocator, self.lockfile.packages.len);
            }
    }
};

