pub fn print(allocator: Allocator, log: *logger.Log, input_lockfile_path: []const u8, format: Format) !void {
            @branchHint(.cold);
            const path = input_lockfile_path[0..@min(input_lockfile_path.len, bun.MAX_PATH_BYTES)];
            var lockfile_path_buf1: bun.PathBuffer = undefined;
            _ = &lockfile_path_buf1;
            var lockfile_path_buf2: bun.PathBuffer = undefined;
            _ = &lockfile_path_buf2;
            var lockfile_path: [:0]const u8 = @as([:0]const u8, "");
            _ = &lockfile_path;
            if ((!std.fs.path.isAbsolute(path))) {
                const cwd = try bun.getcwd((&lockfile_path_buf1));
                var parts: [1][]const u8 = .{ path };
                _ = &parts;
                const lockfile_path__ = Path.joinAbsStringBuf(cwd, (&lockfile_path_buf2), (&parts), .auto);
                lockfile_path_buf2[cp_cast_int(usize, lockfile_path__.len)] = 0;
                lockfile_path = lockfile_path_buf2[0..lockfile_path__.len :0];
            } else {
                if ((path.len > 0)) {
                    _ = @memcpy(lockfile_path_buf1[0..path.len], path);
                    lockfile_path_buf1[cp_cast_int(usize, path.len)] = 0;
                    lockfile_path = lockfile_path_buf1[0..path.len :0];
                }
            }
            if (((lockfile_path.len > 0) and (lockfile_path[0] == std.fs.path.sep))) {
                _ = bun.sys.chdir("", ((std.fs.path.dirname(lockfile_path)) orelse (std.fs.path.sep_str)));
            }
            _ = try FileSystem.init(null);
            var lockfile = try allocator.create(Lockfile);
            _ = &lockfile;
            const load_from_disk = lockfile.loadFromCwd(null, allocator, log, false);
            switch (load_from_disk) {
.err => |cause| {
switch (cause.step) {
.open_file => {
_ = Output.prettyErrorln("<r><red>error<r> opening lockfile:<r> {s}.", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.parse_file => {
_ = Output.prettyErrorln("<r><red>error<r> parsing lockfile:<r> {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.read_file => {
_ = Output.prettyErrorln("<r><red>error<r> reading lockfile:<r> {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.migrating => {
_ = Output.prettyErrorln("<r><red>error<r> while migrating lockfile:<r> {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
}
            if ((log.errors > 0)) {
                _ = try log.print(Output.errorWriter());
            }
            _ = Global.crash();
},
.not_found => {
_ = Output.prettyErrorln("<r><red>lockfile not found:<r> {f}", .{ bun.fmt.QuotedFormatter{ .text = std.mem.sliceAsBytes(lockfile_path) } });
            _ = Global.crash();
},
.ok => {

},
}
            const writer = Output.writerBuffered();
            _ = (blk_catch_0: { break :blk_catch_0 ((printWithLockfile(allocator, lockfile, format, @TypeOf(writer), writer)) catch |e| { _ = &e; if ((e == error.OutOfMemory)) {
                _ = bun.outOfMemory();
            } else {
                if (((e == error.BrokenPipe) or (e == error.WriteFailed))) {
                    return;
                } else {
                    return e;
                }
            } }); });
            _ = Output.flush();
    }

pub fn printWithLockfile(allocator: Allocator, lockfile: *Lockfile, format: Format, comptime Writer: type, writer: Writer) !void {
            var fs = (&FileSystem.instance);
            _ = &fs;
            var options = PackageManager.Options{ .max_concurrent_lifecycle_scripts = 1 };
            _ = &options;
            const entries_option = try fs.fs.readDirectory(fs.top_level_dir, null, 0, true);
            if ((entries_option.* == .err)) {
                return entries_option.err.canonical_error;
            }
            var env_loader: *DotEnv.Loader = brk: {
            const map = try allocator.create(DotEnv.Map);
            map.* = DotEnv.Map.init(allocator);
            const loader = try allocator.create(DotEnv.Loader);
            loader.* = DotEnv.Loader.init(map, allocator);
            loader.quiet = true;
            break :brk loader;
};
            _ = &env_loader;
            _ = try env_loader.loadProcess();
            _ = try env_loader.load(bun.DotEnv.DirEntryKeys.fromDirEntry(entries_option.entries), &.{}, .production, false);
            var log = logger.Log.init(allocator);
            _ = &log;
            _ = try options.load(allocator, (&log), env_loader, null, null, .install);
            var printer = Printer{ .lockfile = lockfile, .options = options };
            _ = &printer;
            switch (format) {
.yarn => {
_ = try Yarn.print((&printer), Writer, writer);
},
}
    }
    pub const Format = _PrinterFormat;
    pub const Tree = TreePrinter;
    pub const Yarn = YarnPrinter;
};

