            self.off = prev_len;
            string_bytes.items = (blk: {
            break :blk string_bytes.items.ptr[0..(string_bytes.items.len + self.cap)];

});
            self.ptr = (blk: {
            break :blk string_bytes.items.ptr[prev_len..(prev_len + self.cap)].ptr;

});
