                _ = assert((self.ptr != null));
            }
            _ = bun.copy(u8, (blk: {
            break :blk self.ptr.?[self.len..self.cap];

}), slice);
            const final_slice = (blk: {
            break :blk self.ptr.?[self.len..self.cap][0..slice.len];

});
            self.len = (self.len + slice.len);
            if (comptime Environment.allow_assert) {
