            }
            return (if (Type == String) String.init(self.lockfile.buffers.string_bytes.items, final_slice) else if (Type == ExternalString) ExternalString.init(self.lockfile.buffers.string_bytes.items, final_slice, hash) else @compileError("Invalid type passed to StringBuilder"));
