            _ = (trusted_dependencies.*).deinit(client.allocator);
        }
        _ = client.patched_dependencies.deinit(client.allocator);
        _ = client.workspace_paths.deinit(client.allocator);
        _ = client.workspace_versions.deinit(client.allocator);
        _ = client.overrides.deinit(client.allocator);
        _ = client.catalogs.deinit(client.allocator);
}

