pub fn resolvePackageFromNameAndVersion(client: *Lockfile, package_name: []const u8, version: Dependency.Version) ?PackageID {
        const name_hash = String.Builder.stringHash(package_name);
        const entry_opt = client.package_index.get(name_hash);
        if ((entry_opt == null)) {
            return null;
        }
        const entry = entry_opt.?;
        const buf = client.buffers.string_bytes.items;
        switch (version.tag) {
.npm => {
switch (entry) {
.id => |id| {
const resolutions = client.packages.items(.resolution);
        if (comptime Environment.allow_assert) {
            _ = assert((id < resolutions.len));
        }
        if (((resolutions[@as(usize, @intCast(id))].tag == .npm) and (if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).npm.version.satisfies((if (@typeInfo(@TypeOf(resolutions[@as(usize, @intCast(id))])) == .@"enum") @intFromEnum(resolutions[@as(usize, @intCast(id))]) else resolutions[@as(usize, @intCast(id))].value).npm.version, buf, buf))) {
            return id;
        }
},
.ids => |ids| {
const resolutions = client.packages.items(.resolution);
        for (ids.items) |id| {
            _ = &id;
            if (comptime Environment.allow_assert) {
                _ = assert((id < resolutions.len));
            }
            if (((resolutions[@as(usize, @intCast(id))].tag == .npm) and (if (@typeInfo(@TypeOf(version)) == .@"enum") @intFromEnum(version) else version.value).npm.version.satisfies((if (@typeInfo(@TypeOf(resolutions[@as(usize, @intCast(id))])) == .@"enum") @intFromEnum(resolutions[@as(usize, @intCast(id))]) else resolutions[@as(usize, @intCast(id))].value).npm.version, buf, buf))) {
                return id;
            }
        }
},
}
},
else => {

},
}
        return null;
}

pub fn hasTrustedDependency(client: *const Lockfile, name: []const u8, resolution: *const Resolution) bool {
        if (client.trusted_dependencies) |trusted_dependencies| {
            _ = &trusted_dependencies;
            const hash = @as(u32, @truncate(String.Builder.stringHash(name)));
            return trusted_dependencies.contains(hash);
        }
        return ((resolution.tag == .npm) and default_trusted_dependencies.has(name));
}
